"""Prints test/cache_lab_cases.inc: expected L1D (and RVSS I$) counts from the Python oracle.
usage: gen_cases.py > test/cache_lab_cases.inc"""
import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "lib"))
import oracle
import vpaths
repo = vpaths.ROOT
CONFIGS = ["dm256", "2w128fifo"]
out = ["// Generated by verification/cache/gen_cases.py from an independent Python cache model",
       "// (cachemodel.py + miniiss.py), never from the simulator. Do not edit by hand.",
       "// { benchmark, config, sets, ways, lineBytes, fifo, writeBack, writeAllocate,",
       "//   L1D hits, misses, evictions, I$ hits, I$ misses (RVSS order) }"]
for s in (1, 2, 4, 8, 16, 32):
    b = f"stride_{s}"
    src = open(os.path.join(repo, "examples/cache_lab", b + ".s")).read()
    for c in CONFIGS:
        sets, ways, line, pol, wb, wa = oracle.CONFIGS[c]
        e = oracle.expect(src, oracle.CONFIGS[c])
        d, i = e["L1D"], e["I"]
        out.append(f'{{"{b}", "{c}", {sets}, {ways}, {line}, {str(pol == "FIFO").lower()}, '
                   f'{str(bool(wb)).lower()}, {str(bool(wa)).lower()}, '
                   f'{d["hits"]}, {d["misses"]}, {d["evictions"]}, {i["hits"]}, {i["misses"]}}},')
sys.stdout.write("\n".join(out) + "\n")
